mapper.select:
SELECT e.exam_id AS examId, e.title AS title, e.exam_type AS examType, e.exam_date AS examDate,
( SELECT COUNT(*) FROM exam_answers ea JOIN exam_attempts a ON ea.attempt_id = a.attempt_id WHERE a.exam_id = e.exam_id AND a.student_id = #{studentId} AND a.attempt_type = 'EXAM' AND a.status = 'GRADED' AND ea.is_correct = FALSE ) AS wrongCount
FROM exams e
JOIN class_students cs ON e.class_id = cs.class_id
WHERE cs.student_id = #{studentId}
AND e.exam_date = #{date}
ORDER BY e.exam_date DESC, e.exam_id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)

FROM exams e

JOIN class_students cs
ON e.class_id = cs.class_id

WHERE cs.student_id = #{studentId}


    AND e.exam_date = #{date}

SELECT exam_id AS examId, class_id AS classId, teacher_id AS teacherId, title, exam_type AS examType, exam_mode AS examMode, exam_round AS examRound, status, exam_date AS examDate, file_url AS fileUrl
FROM exams
WHERE exam_id = #{examId}

SELECT question_id, exam_id, section_id, question_number, question_type, question_type_tag, score, correct_answer, question_text, passage, sort_order
FROM exam_questions
WHERE question_id = #{questionId}

SELECT COALESCE(MAX(attempt_no), 0) + 1

FROM exam_attempts

WHERE exam_id = #{examId}
  AND student_id = #{studentId}

mapper.update:
UPDATE exam_attempts
SET status = 'GRADED', total_score = #{totalScore}, max_score = #{maxScore}, correct_count = #{correctCount}, total_question_count = #{totalQuestionCount}, submitted_at = NOW(), graded_at = NOW()
WHERE attempt_id = #{attemptId}

mapper.select:
SELECT attempt_id, exam_id, student_id, attempt_no, attempt_type, source_attempt_id, entry_method, status, total_score, max_score, correct_count, total_question_count, started_at, submitted_at, graded_at
FROM exam_attempts
WHERE attempt_id = #{attemptId}

mapper.update:
UPDATE daily_review_attempts
SET status = 'GRADED', total_score = #{totalScore}, max_score = #{maxScore}, correct_count = #{correctCount}, total_question_count = #{totalQuestionCount}, submitted_at = NOW(), graded_at = NOW()
WHERE daily_review_attempt_id = #{dailyReviewAttemptId}

mapper.select:
SELECT daily_review_attempt_id AS dailyReviewAttemptId, student_id AS studentId, review_date AS reviewDate, status, total_score AS totalScore, max_score AS maxScore, correct_count AS correctCount, total_question_count AS totalQuestionCount, started_at AS startedAt, submitted_at AS submittedAt, graded_at AS gradedAt
FROM daily_review_attempts
WHERE daily_review_attempt_id = #{dailyReviewAttemptId}
